import { createRouter } from '@tanstack/react-router'

import { queryClient } from '@/lib/query/client'
import { routeTree } from '@/routeTree.gen'

/**
 * Single router instance.
 *
 * - `defaultPreload: 'intent'` warms route code on hover/focus;
 * - `scrollRestoration` keeps the catalog position when navigating back;
 * - the context carries the QueryClient so loaders read/write the same cache.
 *
 * `src/routeTree.gen.ts` is generated by @tanstack/router-plugin on `dev`/`build`.
 */
export const router = createRouter({
  routeTree,
  context: { queryClient },
  defaultPreload: 'intent',
  defaultPreloadStaleTime: 0,
  scrollRestoration: true,
})

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}
